#!/usr/bin/env python3
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# Studio.Surface (REQ-AGENT-INTERFACE): the workspace API's operations, published as MCP Tool definitions in
# surface/mcp-tools.json, must be a ListToolsResult of the bound MCP-SCHEMA-2026-07-28. This validates it against
# that schema's own definitions (type, required, properties, items, enum, const, additionalProperties, $ref), and
# requires every tool's inputSchema to be a JSON Schema object, one tool for each operation the usage lists.
import json, sys
TYPES = {'object': dict, 'array': list, 'string': str, 'boolean': bool, 'null': type(None)}
schema = json.load(open('authorities' + chr(47) + 'MCP-SCHEMA-2026-07-28' + chr(47) + 'schema.json'))
defs = schema['$defs']

def numeric(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)

def check(value, rule, where, problems):
    if not isinstance(rule, dict):
        return
    if '$ref' in rule:
        check(value, defs[rule['$ref'].split(chr(47))[-1]], where, problems)
    kinds = rule.get('type')
    if kinds is not None:
        kinds = kinds if isinstance(kinds, list) else [kinds]
        fits = any((kind in ('number', 'integer') and numeric(value)) or (kind in TYPES and isinstance(value, TYPES[kind])) for kind in kinds)
        if not fits:
            problems.append(where + ' is not of type ' + repr(kinds))
            return
    if 'enum' in rule and value not in rule['enum']:
        problems.append(where + ' is not one of ' + repr(rule['enum']))
    if 'const' in rule and value != rule['const']:
        problems.append(where + ' is not ' + repr(rule['const']))
    if isinstance(value, dict):
        for name in rule.get('required', []):
            if name not in value:
                problems.append(where + ' lacks ' + name)
        known = rule.get('properties', {})
        for name, item in value.items():
            if name in known:
                check(item, known[name], where + '.' + name, problems)
            elif rule.get('additionalProperties') is False:
                problems.append(where + ' has ' + name + ', which the schema does not allow')
            else:
                check(item, rule.get('additionalProperties'), where + '.' + name, problems)
    if isinstance(value, list) and 'items' in rule:
        for index, item in enumerate(value):
            check(item, rule['items'], where + '[' + str(index) + ']', problems)

result = json.load(open('surface' + chr(47) + 'mcp-tools.json'))
problems = []
check(result, defs['ListToolsResult'], 'tools-list', problems)
names = [tool.get('name') for tool in result.get('tools', [])]
if len(names) != len(set(names)):
    problems.append('tools-list names a tool twice')
for tool in result.get('tools', []):
    shape = tool.get('inputSchema', {})
    for name in shape.get('required', []):
        if name not in shape.get('properties', {}):
            problems.append(tool.get('name', '?') + ' requires ' + name + ', which it does not define')
for problem in problems:
    print('::error::surface' + chr(47) + 'mcp-tools.json ' + problem)
if not problems:
    print('accepted: surface' + chr(47) + 'mcp-tools.json holds ' + str(len(names)) + ' MCP tools, valid against MCP-SCHEMA-2026-07-28')
sys.exit(1 if problems else 0)
